def parse_markdown_file(filepath, options, para_counter_start=1, link_counter_start=1):
    # Returns list of sections (each with html content, title, etc) and footnotes dict, and stats
    try:
        with open(filepath, "r", encoding="utf-8", errors="ignore") as f:
            content = f.read()
    except:
        return None, None, None

    # Handle YAML blocks at top of file if input.yaml_blocks true
    # YAML block is delimited by --- at start and --- or ... ?
    # In single mode, the file may have YAML frontmatter delimited by --- lines
    # In book mode with yaml_blocks enabled, similar inline YAML blocks can appear?
    # For simplicity, if options input.yaml_blocks true or single mode, check if content starts with ---\n and has closing ---\n
    yaml_options = {}
    remaining = content
    if options.get("input.yaml_blocks", False) or options.get("single_mode", False):
        # Check for leading ---
        if content.startswith("---\n"):
            # Find closing ---
            # It could be "---\n" or "...\n" or "---" at end
            # Split
            parts = content.split("\n---", 1)
            # Actually need to find second --- on its own line
            # We'll use regex
            m = re.match(r'^---\n(.*?)\n---\n?(.*)', content, re.DOTALL)
            if m:
                yaml_block = m.group(1)
                remaining = m.group(2)
                # Parse yaml_block as simple key: value
                for line in yaml_block.split("\n"):
                    line=line.strip()
                    if not line or line.startswith("#"):
                        continue
                    if ":" in line:
                        k,v = line.split(":",1)
                        k=k.strip()
                        v=v.strip()
                        # Remove surrounding quotes if any
                        if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
                            v=v[1:-1]
                        yaml_options[k]=v

    # Now process remaining markdown for cleaning
    lang = options.get("lang","en")
    smart_quotes = options.get("input.clean.smart_quotes", True)
    lig_dashes = options.get("input.clean.ligature.dashes", False)
    lig_guil = options.get("input.clean.ligature.guillemets", False)
    clean = options.get("input.clean", True)

    # We'll split into blocks by blank lines
    # But need to handle code blocks, blockquotes, lists, etc.

    # For simplicity, we'll parse line by line

    lines = remaining.split("\n")
    # We'll produce sections: each time we encounter h1, new section starts
    sections = []
    current_section = {"title": "", "level": 0, "content_blocks": [], "para_ids": [], "footnotes": {}}
