    list_stack = []  # stack of list types
    table_lines = []
    in_table = False

    # For paragraph accumulation
    para_buffer = []

    def flush_para():
        nonlocal para_buffer, para_counter, current_section
        if not para_buffer:
            return
        para_text = " ".join(para_buffer).strip()
        para_buffer = []
        if not para_text:
            return
        # Clean
        para_text = clean_text(para_text, lang=lang, smart_quotes=smart_quotes, ligature_dashes=lig_dashes, ligature_guillemets=lig_guil, clean=clean)
        # Parse inline
        para_html_inner = parse_inline(para_text, options)
        # Wrap in p with id
        para_html = f'<p id = "para-{para_counter}">{para_html_inner}</p>'
        para_counter += 1
        current_section["content_blocks"].append(para_html)
        current_section["para_ids"].append(para_counter-1)

    # We also need to handle horizontal rule
    def flush_blockquote():
        nonlocal blockquote_lines, para_counter, current_section, in_blockquote
        if not blockquote_lines:
