        header_cells = split_cells(header)
        html = '<div class = "table">\n    <table>\n<tr>\n'
        for hc in header_cells:
            hc_clean = clean_text(hc, lang=lang, smart_quotes=smart_quotes, ligature_dashes=lig_dashes, ligature_guillemets=lig_guil, clean=clean)
            hc_inline = parse_inline(hc_clean, options)
